//! Native board and fleet command families.
//!
//! Human output is deliberately a projection of the same JSON values returned by the stable
//! `flux.cli/v1` agent API. Repository planning files remain authoritative; the small state files
//! below contain only CLI concurrency/idempotency and fleet runtime facts.

use super::*;
use serde::{Deserialize, Serialize};
use serde_json::{json, Map, Value};
use std::cmp::Ordering as CmpOrdering;
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::hash::{Hash, Hasher};
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::time::Duration;

const CLI_SCHEMA: &str = "flux.cli/v1";
const BEGIN: &str = "<!-- BEGIN track:board -->";
const END: &str = "<!-- END track:board -->";
const GENERATED_NOTE: &str = "<!-- Generated by /track:board (track plugin) from story frontmatter. Do not hand-edit this region; edit the stories and re-run /track:board. -->";
const STATUSES: [&str; 5] = ["backlog", "ready", "in-progress", "blocked", "done"];
const CONTROL_PROCESS_TIMEOUT: Duration = Duration::from_secs(60 * 60);
const FLEET_STREAM_JSON_LINE_LIMIT: usize = 240 * 1024;

fn guarded_system(root: &Path) -> Result<flux_system::System> {
    flux_system::System::from_env(root).map_err(|error| anyhow::anyhow!(error.to_string()))
}

/// Run trusted control-plane argv through Flux's one guarded process boundary.
///
/// Board/fleet commands are synchronous projections inside the CLI's multi-thread Tokio runtime.
/// `block_in_place` lets them use the async System port without constructing a second runtime or a
/// raw `Command`. The one-hour ceiling is deliberately finite: a wedged gate remains inspectable
/// and cancellable instead of pinning the coordinator forever.
fn guarded_run(root: &Path, argv: &[String]) -> Result<flux_system::ProcessOutput> {
    if argv.is_empty() {
        bail!("input/schema: process argv cannot be empty")
    }
    let system = guarded_system(root)?;
    tokio::task::block_in_place(|| {
        tokio::runtime::Handle::current()
            .block_on(system.run(argv, CONTROL_PROCESS_TIMEOUT))
            .map_err(|error| anyhow::anyhow!(error.to_string()))
    })
}

/// Retain only complete newest lines within `limit` bytes.
///
/// Agent stream events are one JSON object per line. Cutting bytes from the front of an oversized
/// in-flight line creates invalid JSON and can hide a later terminal event. Once a line itself
/// exceeds the window, discard that whole line through its newline, then resume capture at the next
/// event. This keeps memory bounded and every retained line parseable.
fn append_capped_line_buffer(
    buffer: &mut Vec<u8>,
    dropping_line: &mut bool,
    bytes: &[u8],
    limit: usize,
) {
    if limit == 0 {
        buffer.clear();
        *dropping_line = !bytes.ends_with(b"\n");
        return;
    }
    let mut remaining = bytes;
    if *dropping_line {
        let Some(newline) = remaining.iter().position(|byte| *byte == b'\n') else {
            return;
        };
        remaining = &remaining[newline + 1..];
        *dropping_line = false;
    }
    buffer.extend_from_slice(remaining);
    while buffer.len() > limit {
        if let Some(newline) = buffer.iter().position(|byte| *byte == b'\n') {
            buffer.drain(..=newline);
        } else {
            buffer.clear();
            *dropping_line = true;
            break;
        }
    }
}

fn guarded_git(root: &Path, args: &[&str]) -> Result<flux_system::ProcessOutput> {
    let argv = std::iter::once("git".to_string())
        .chain(args.iter().map(|argument| (*argument).to_string()))
        .collect::<Vec<_>>();
    guarded_run(root, &argv)
}

/// Did this validation run execute zero tests?
///
/// A filtered-to-nothing run is not a pass and not a failure — it is "the cited test does not exist
/// here". Detected from the runner's own summary rather than the exit code, because `cargo test`
/// reports `0 passed; 0 failed; N filtered out` and exits 0. Recognises the libtest summary shared by
/// `cargo test`/`cargo nextest`; an unrecognised runner simply reports `false` and keeps the strict
/// exit-code contract.
///
/// **Every summary is counted, not the presence of one string.** `cargo test -p <pkg> <filter>` runs the
/// package's lib unittests *and* each of its integration-test binaries, so a filter that matches one
/// target emits a real summary for that target and `0 passed; 0 failed; N filtered out` for every other.
/// A substring search over the combined output therefore reported "no tests ran" for a run in which a
/// test genuinely ran and passed — which silently refused a correct handoff and parked a wave holding
/// delivered work. The question is whether ANY target executed a test, so the counts are summed.
fn ran_no_tests(evidence: &Value) -> bool {
    let haystack = format!(
        "{}{}",
        evidence["stdout"].as_str().unwrap_or_default(),
        evidence["stderr"].as_str().unwrap_or_default()
    );
    /// Read the integer immediately preceding `marker` (`"4 passed"` → `4`).
    fn count_before(line: &str, marker: &str) -> Option<u64> {
        let head = &line[..line.find(marker)?];
        let digits = head
            .trim_end()
            .rsplit(|c: char| !c.is_ascii_digit())
            .next()?;
        digits.parse().ok()
    }
    let mut recognised = false;
    let mut executed = 0u64;
    for line in haystack.lines() {
        // libtest: `test result: ok. 1 passed; 0 failed; 293 filtered out; ...`
        if line.contains("test result:") {
            recognised = true;
            executed += count_before(line, " passed").unwrap_or(0);
            executed += count_before(line, " failed").unwrap_or(0);
        }
        // nextest: `Summary [ 0.1s] 4 tests run: 4 passed, 0 skipped` / `Starting 4 tests across ...`
        else if line.contains(" tests run") {
            recognised = true;
            executed += count_before(line, " tests run").unwrap_or(0);
        } else if line.contains("Starting ") && line.contains(" tests") {
            recognised = true;
            executed += count_before(line, " tests").unwrap_or(0);
        }
    }
    recognised && executed == 0
}

/// Sidecar carrying live worker activity, relative to the Fleet root.
///
/// A wave writes `state.json` exactly twice — once before the first worker starts, once after the
/// last joins — so for the whole wave a surface has nothing new to render and an operator watching
/// `flux tui --fleet` sees a frozen panel. The worker's NDJSON is already arriving on stdout; this
/// file is where the supervisor lands a bounded projection of it as it arrives, so a surface can
/// tail one path instead of deriving five per-worker store paths.
pub(super) const FLEET_ACTIVITY_SIDECAR: &str = ".flux/fleet/activity.ndjson";
/// Keep the sidecar bounded: it is a live view, not an archive. Full fidelity stays in each worker's
/// own session store and in the turn receipt.
const FLEET_ACTIVITY_MAX_BYTES: u64 = 2 * 1024 * 1024;

/// Append one bounded activity record for `agent_id`.
///
/// Deliberately structural only — event type, operation name, and a coarse outcome. Tool inputs and
/// result bodies are never read, so a worker's secrets cannot reach this file through a field it does
/// not touch (the same property A-79's `SpawnActivity` relies on). Best-effort: a surface losing an
/// activity line must never fail a worker's turn, so every error here is swallowed.
fn append_worker_activity(fleet_root: &Path, agent_id: &str, line: &str) {
    let Ok(event) = serde_json::from_str::<Value>(line) else {
        return;
    };
    let kind = event["type"].as_str().unwrap_or("event");
    // `turn_start` carries the whole prompt; it is stripped from receipts too. Skip it entirely.
    if kind == "turn_start" {
        return;
    }
    let subject = ["name", "operation", "stage", "original_type"]
        .into_iter()
        .find_map(|key| event[key].as_str())
        .unwrap_or("—");
    let outcome = if event["is_error"].as_bool() == Some(true) {
        "error"
    } else {
        event["outcome"].as_str().unwrap_or("ok")
    };
    let record = json!({
        "schema": "flux.fleet-activity/v1",
        "agent": agent_id,
        "type": kind,
        "operation": bounded_text(subject, 80),
        "outcome": outcome,
    });
    let path = fleet_root.join(FLEET_ACTIVITY_SIDECAR);
    if std::fs::metadata(&path).map(|meta| meta.len()).unwrap_or(0) > FLEET_ACTIVITY_MAX_BYTES {
        let _ = std::fs::remove_file(&path);
    }
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    use std::io::Write as _;
    if let Ok(mut file) = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
    {
        let _ = writeln!(file, "{record}");
    }
}

/// Read the activity sidecar into the last few lines per worker, newest last.
///
/// Best-effort and bounded: a missing, truncated or partially written sidecar yields whatever parses,
/// because a live view must never fail a snapshot the operator is waiting on.
fn read_worker_activity(root: &Path) -> BTreeMap<String, Vec<String>> {
    const MAX_PER_WORKER: usize = 20;
    let mut out: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let Ok(text) = std::fs::read_to_string(root.join(FLEET_ACTIVITY_SIDECAR)) else {
        return out;
    };
    for line in text.lines() {
        let Ok(record) = serde_json::from_str::<Value>(line) else {
            continue;
        };
        let Some(agent) = record["agent"].as_str() else {
            continue;
        };
        let summary = format!(
            "{} · {} · {}",
            record["type"].as_str().unwrap_or("event"),
            record["operation"].as_str().unwrap_or("—"),
            record["outcome"].as_str().unwrap_or("ok"),
        );
        let entries = out.entry(agent.to_string()).or_default();
        entries.push(bounded_text(&summary, 300));
        if entries.len() > MAX_PER_WORKER {
            entries.remove(0);
        }
    }
    out
}

/// Feed newly arrived stdout bytes to [`append_worker_activity`], one complete line at a time.
/// Returns the unconsumed tail (a partial line) to be carried into the next poll.
fn drain_activity_lines(pending: &mut String, chunk: &str, fleet_root: &Path, agent_id: &str) {
    pending.push_str(chunk);
    while let Some(newline) = pending.find('\n') {
        let line = pending[..newline].trim().to_string();
        pending.drain(..=newline);
        if !line.is_empty() {
            append_worker_activity(fleet_root, agent_id, &line);
        }
    }
    // A single absurdly long line must not grow this buffer without bound.
    if pending.len() > FLEET_STREAM_JSON_LINE_LIMIT {
        pending.clear();
    }
}

async fn guarded_agent_run_async(
    worktree: &Path,
    read_roots: &[PathBuf],
    fleet_root: &Path,
    agent_id: &str,
    environment: &[(String, String)],
    argv: &[String],
) -> Result<flux_system::ProcessOutput> {
    const CAPTURE_LIMIT: usize = 1024 * 1024;
    let mut workspace = flux_system::Workspace::from_env(worktree)
        .map_err(|error| anyhow::anyhow!(error.to_string()))?;
    for root in read_roots {
        workspace
            .add_read_root(root)
            .map_err(|error| anyhow::anyhow!(error.to_string()))?;
    }
    // C-607: pin the worker's confinement here rather than inheriting whatever the operator's shell
    // resolved. `flux fleet run` is operator-invoked and must stay unconfined itself — it creates
    // worktrees in each member repository's shared git dir, outside any single workspace — but the
    // turn it launches has no approval boundary at all, which is exactly C-262's criterion. Left to
    // `from_env`, an operator with no `FLUX_SANDBOX` set resolved `Off` and the worker was spawned
    // unwrapped, making the workspace path guard its only confinement of any kind (and that guard does
    // not cover `bash`/`proc.run`, nor does the OS sandbox restrict reads on either backend).
    // C-607 is NOT fixed here yet, deliberately. Forcing `SandboxMode::On` at this spawn site does
    // confine the worker, but it also made every worker turn fail with
    // `emitted an invalid event stream` — reproducibly, where the same story committed successfully
    // without it. The parse error is masked by the context message (which shows only stderr, carrying
    // the child's `trusting FLUX_SANDBOXED=1` startup warning), so the mechanism is not yet
    // established: it may be the child's own startup output reaching stdout and corrupting the NDJSON
    // protocol, or the wrapped spawn changing how output is delivered.
    //
    // Leaving the fleet unable to do any work is worse than the exposure this closes, so the posture
    // stays inherited until the stream failure is understood. The exposure is real and documented in
    // C-607: with no `FLUX_SANDBOX` set, a worker resolves `Off` and is spawned unwrapped, so the
    // workspace path guard is its only confinement — and that guard does not cover `bash`/`proc.run`,
    // which C-606 has now removed from the default story capabilities.
    let system = flux_system::System::new(workspace).with_sandbox(
        flux_system::sandbox::Sandbox::resolve(flux_system::sandbox::SandboxSettings::from_env()),
    );
    let argv = argv.to_vec();
    let fleet_root = fleet_root.to_path_buf();
    let agent_id = agent_id.to_string();
    let mut environment = environment.to_vec();
    environment.push((
        crate::stream_json::STREAM_JSON_LINE_LIMIT_ENV.to_string(),
        FLEET_STREAM_JSON_LINE_LIMIT.to_string(),
    ));
    let mut child = system
        .spawn_background(&argv, &environment)
        .map_err(|error| anyhow::anyhow!(error.to_string()))?;
    let deadline = tokio::time::Instant::now() + CONTROL_PROCESS_TIMEOUT;
    let mut stdout = Vec::new();
    let mut stderr = Vec::new();
    let mut dropping_stdout_line = false;
    let mut dropping_stderr_line = false;
    let mut activity_pending = String::new();
    loop {
        let (out, err) = child.read_output();
        // Project each complete line to the activity sidecar as it arrives. This poll loop is the
        // only place that sees worker events before the process exits.
        drain_activity_lines(&mut activity_pending, &out, &fleet_root, &agent_id);
        append_capped_line_buffer(
            &mut stdout,
            &mut dropping_stdout_line,
            out.as_bytes(),
            CAPTURE_LIMIT,
        );
        append_capped_line_buffer(
            &mut stderr,
            &mut dropping_stderr_line,
            err.as_bytes(),
            CAPTURE_LIMIT,
        );
        let status = child.status();
        if !status.running {
            // The child can exit a few scheduler ticks before the async pipe drains publish their
            // final bytes. Collect that bounded tail so `turn_end` is never lost at process exit.
            for _ in 0..5 {
                tokio::time::sleep(Duration::from_millis(10)).await;
                let (out, err) = child.read_output();
                append_capped_line_buffer(
                    &mut stdout,
                    &mut dropping_stdout_line,
                    out.as_bytes(),
                    CAPTURE_LIMIT,
                );
                append_capped_line_buffer(
                    &mut stderr,
                    &mut dropping_stderr_line,
                    err.as_bytes(),
                    CAPTURE_LIMIT,
                );
            }
            return Ok(flux_system::ProcessOutput {
                stdout: String::from_utf8_lossy(&stdout).into_owned(),
                stderr: String::from_utf8_lossy(&stderr).into_owned(),
                exit_code: status.exit_code.unwrap_or(-1),
            });
        }
        let cancelled = read_fleet_state(&fleet_root).ok().is_some_and(|state| {
            if agent_id == "main" {
                state.main_agent.status == "cancelled"
            } else {
                state.agents[&agent_id]["status"].as_str() == Some("cancelled")
            }
        });
        if cancelled {
            child.kill();
            bail!("transient-worker: agent {agent_id} was cancelled by the durable fleet state")
        }
        if tokio::time::Instant::now() >= deadline {
            child.kill();
            bail!("transient-worker: agent {agent_id} exceeded the one-hour turn deadline")
        }
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

fn guarded_agent_run(
    worktree: &Path,
    read_roots: &[PathBuf],
    fleet_root: &Path,
    agent_id: &str,
    environment: &[(String, String)],
    argv: &[String],
) -> Result<flux_system::ProcessOutput> {
    tokio::task::block_in_place(|| {
        tokio::runtime::Handle::current().block_on(guarded_agent_run_async(
            worktree,
            read_roots,
            fleet_root,
            agent_id,
            environment,
            argv,
        ))
    })
}

fn guarded_agent_run_on(
    runtime: &tokio::runtime::Handle,
    worktree: &Path,
    read_roots: &[PathBuf],
    fleet_root: &Path,
    agent_id: &str,
    environment: &[(String, String)],
    argv: &[String],
) -> Result<flux_system::ProcessOutput> {
    runtime.block_on(guarded_agent_run_async(
        worktree,
        read_roots,
        fleet_root,
        agent_id,
        environment,
        argv,
    ))
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub(super) enum AgentOutput {
    #[default]
    Human,
    Json,
    Ndjson,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum BoardScopeArg {
    Session,
    #[default]
    Repository,
    Workspace,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum BoardProfileArg {
    General,
    #[default]
    Planning,
    Execution,
}

#[derive(clap::Args, Debug)]
pub(super) struct BoardCommand {
    /// Board root. Repository boards default to the current directory.
    #[arg(long, value_name = "DIR", default_value = ".", global = true)]
    root: PathBuf,
    /// Explicit board binding. Required when more than one compatible board is registered.
    #[arg(long, global = true)]
    board: Option<String>,
    /// Board lifetime/authority scope; independent of profile and backend.
    #[arg(long, value_enum, global = true)]
    scope: Option<BoardScopeArg>,
    /// Operation/state-machine profile; independent of scope and backend.
    #[arg(long, value_enum, default_value_t, global = true)]
    profile: BoardProfileArg,
    /// Output encoding. JSON/NDJSON, not human prose, is the automation API.
    #[arg(long, value_enum, default_value_t, global = true)]
    output: AgentOutput,
    /// Read one `flux.cli/v1` JSON request from a file or stdin (`-`).
    #[arg(long, value_name = "FILE|-", global = true)]
    request: Option<String>,
    /// Stable key for retrying a mutating request without applying it twice.
    #[arg(long, global = true)]
    idempotency_key: Option<String>,
    /// Refuse a mutation unless the board still has this revision.
    #[arg(long, global = true)]
    if_revision: Option<String>,
    /// Validate and return the proposed result without writing.
    #[arg(long, global = true)]
    dry_run: bool,
    /// Session board owner when invoked outside a live turn (`last` is accepted).
    #[arg(long, global = true)]
    session: Option<String>,
    #[command(subcommand)]
    action: BoardAction,
}

#[derive(clap::Subcommand, Debug)]
pub(super) enum BoardAction {
    /// Scaffold a Track-compatible repository board.
    Init {
        #[arg(long)]
        scaffold: bool,
    },
    /// List discovered board bindings.
    #[command(visible_alias = "ls")]
    List,
    /// Show the selected board and its planning documents.
    Show,
    /// List all items in deterministic order.
    Items,
    /// Read one item.
    Get { id: String },
    /// Query items by planning status, area or text.
    Query {
        #[arg(long)]
        status: Option<String>,
        #[arg(long)]
        area: Option<String>,
        #[arg(long)]
        text: Option<String>,
    },
    /// Return dependency-satisfied ready items in priority order.
    Next {
        #[arg(long, default_value_t = 1)]
        limit: usize,
        #[arg(long)]
        area: Option<String>,
        /// Return the largest wave-safe set instead of the highest-priority prefix.
        ///
        /// Dependency satisfaction says only that nothing an item *waits on* is outstanding. It
        /// says nothing about whether two ready items can be built at the same time, and
        /// integration refuses a wave in which two stories wrote the same path. Priority clusters
        /// by subject, and subject is what predicts collisions, so the highest-priority `--limit`
        /// items are often the worst possible wave.
        #[arg(long)]
        independent: bool,
    },
    /// Create a story, epic or design without clobbering an existing file.
    Create {
        #[arg(long, value_enum, default_value_t)]
        kind: CreateKind,
        #[arg(long)]
        id: Option<String>,
        #[arg(long)]
        title: String,
        #[arg(long, default_value = "Core")]
        pillar: String,
        #[arg(long, default_value = "backlog")]
        status: String,
        #[arg(long)]
        priority: Option<i64>,
        #[arg(long)]
        epic: Option<String>,
        #[arg(long = "area")]
        areas: Vec<String>,
        #[arg(long)]
        design: Option<String>,
        #[arg(long)]
        note: Option<String>,
        /// Leave the new document uncommitted. It will not be visible to any board read that resolves
        /// items at a git ref, which is the default for a workspace member.
        #[arg(long)]
        no_commit: bool,
    },
    /// Update common planning metadata.
    Update {
        id: String,
        #[arg(long)]
        title: Option<String>,
        #[arg(long)]
        priority: Option<i64>,
        #[arg(long)]
        note: Option<String>,
    },
    /// Apply one profile-valid item transition.
    Transition { id: String, status: String },
    /// Move a planning item to `in-progress`.
    Start { id: String },
    /// Block an item and record why.
    Block {
        id: String,
        #[arg(long)]
        reason: String,
    },
    /// Return a blocked planning item to ready.
    Unblock { id: String },
    /// Complete a story after verifying all Acceptance checkboxes.
    Done {
        id: String,
        #[arg(long = "override-reason")]
        override_reason: Option<String>,
        #[arg(long)]
        changelog: Option<String>,
    },
    /// Append a durable item comment.
    Comment { id: String, text: String },
    /// Append structured evidence to an item.
    Evidence { id: String, evidence: String },
    /// Validate frontmatter, ids, priorities and planning-document links.
    Check,
    /// Regenerate the Track marker region byte-for-byte compatibly.
    Render,
    /// Validate then render the selected board.
    Sync,
    /// Return item/dependency graph data.
    Graph,
    /// Return the exact board metric cube.
    Stats {
        #[arg(long)]
        history: bool,
        #[arg(long)]
        since: Option<String>,
    },
    /// Render the metric cube without recalculating it.
    Report {
        #[arg(long, value_enum, default_value_t)]
        format: ReportFormat,
        #[arg(short = 'o', long)]
        out: Option<PathBuf>,
        #[arg(long)]
        history: bool,
    },
    /// Import a versioned board JSON document.
    Import { path: String },
    /// Export the selected board as versioned JSON.
    Export {
        #[arg(short = 'o', long)]
        out: Option<PathBuf>,
    },
    /// Manage the revisioned vision singleton.
    Vision {
        #[command(subcommand)]
        action: SingletonDocAction,
    },
    /// Manage the revisioned roadmap singleton.
    Roadmap {
        #[command(subcommand)]
        action: SingletonDocAction,
    },
    /// Manage stable proposed/accepted/superseded decisions.
    Decision {
        #[command(subcommand)]
        action: DecisionAction,
    },
    /// Manage linked design documents (not queue items).
    Design {
        #[command(subcommand)]
        action: DesignAction,
    },
    /// Publish the exact operation/request/response catalogue.
    Schema,
    /// Invoke an operation with a JSON request (the automation escape hatch).
    Call {
        /// Board binding, or the operation when `--board` already selects a binding.
        target: String,
        /// Operation when the first positional argument is a board binding.
        operation: Option<String>,
    },
    /// Render a concise, version-matched Agent Skill guide.
    Skill,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(super) enum CreateKind {
    #[default]
    Story,
    Epic,
    Design,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Default)]
pub(super) enum ReportFormat {
    #[default]
    Json,
    Tsv,
    Html,
    Svg,
}

#[derive(clap::Subcommand, Debug)]
pub(super) enum SingletonDocAction {
    Show,
    Set {
        #[arg(long, conflicts_with = "file", required_unless_present = "file")]
        content: Option<String>,
        #[arg(long, conflicts_with = "content", required_unless_present = "content")]
        file: Option<String>,
    },
}

#[derive(clap::Subcommand, Debug)]
pub(super) enum DecisionAction {
    List {
        #[arg(long)]
        status: Option<String>,
    },
    Show {
        id: String,
    },
    Create {
        id: String,
        #[arg(long)]
        title: String,
        #[arg(long)]
        content: Option<String>,
    },
    /// Open a human decision and block only the explicitly linked stories.
    Open {
        id: String,
        #[arg(long)]
        title: String,
        #[arg(long)]
        question: String,
        #[arg(long = "blocks")]
        blocks: Vec<String>,
        /// Candidate outcome. Repeat to provide a compact pick-list.
        #[arg(long = "option")]
        options: Vec<String>,
        /// Trade-off for an option, as OPTION=DETAIL. Repeat for structured suggestions.
        #[arg(long = "tradeoff", value_name = "OPTION=DETAIL")]
        tradeoffs: Vec<String>,
        /// The proposing agent's preferred option; an auto reviewer must challenge it.
        #[arg(long)]
        recommended: Option<String>,
    },
    Update {
        id: String,
        #[arg(long)]
        content: String,
    },
    Accept {
        id: String,
    },
    /// Record the human outcome and return linked stories to their previous state.
    Decide {
        id: String,
        #[arg(long)]
        outcome: String,
        #[arg(long)]
        rationale: Option<String>,
    },
    Supersede {
        id: String,
        #[arg(long)]
        by: String,
    },
}

